import express from 'express';
export const app = express();
app.post('/integrations/github/webhook', express.json(), (req, res) => {
  const kind = req.header('x-github-event');
  res.locals.delivery = { kind, repository: req.body.repository };
  return res.sendStatus(202);
});

import { Webhook } from 'svix';
export async function POST(req: Request) {
  const verifier = new Webhook(process.env.SVIX_WEBHOOK_SECRET!);
  try {
    const event = verifier.verify(await req.text(), {
      'svix-id': req.headers.get('svix-id') || '',
      'svix-timestamp': req.headers.get('svix-timestamp') || '',
      'svix-signature': req.headers.get('svix-signature') || ''
    });
    return Response.json({ received: Boolean(event) });
  } catch {
    return new Response('Rejected', { status: 400 });
  }
}

