import express from 'express';
import { Webhooks } from '@octokit/webhooks';
export const router = express.Router();
const verifier = new Webhooks({ secret: process.env.GITHUB_WEBHOOK_SECRET });
router.post('/integrations/github/webhook', express.text({ type: 'application/json' }), async (req, res) => {
  const ok = await verifier.verify(req.body, req.get('x-hub-signature-256') || '');
  if (!ok) return res.sendStatus(401);
  const event = JSON.parse(req.body);
  return res.json({ repository: event.repository.name });
});

