import { Hono } from 'hono';
import { Webhooks } from '@octokit/webhooks';
export const app = new Hono();
const verifier = new Webhooks({ secret: process.env.GITHUB_WEBHOOK_SECRET! });
app.post('/hooks/github', async ctx => {
  const text = await ctx.req.text();
  if (!(await verifier.verify(text, ctx.req.header('x-hub-signature-256') || ''))) {
    return ctx.text('Rejected', 401);
  }
  const data = JSON.parse(text);
  return ctx.json({ action: data.action });
});

import express from 'express';
