const seen = new Set();

export default {
  async fetch(request) {
    const path = new URL(request.url).pathname;
    if (request.method !== "POST" || path !== "/webhooks/svix") {
      return new Response(null, { status: 404 });
    }
    const event = await request.json();
    seen.add(event.id);
    return new Response(null, { status: 202 });
  }
};

