import express from "express";
import { Webhooks } from "@octokit/webhooks";

const webhooks = new Webhooks({ secret: process.env.GITHUB_WEBHOOK_SECRET });
const types = [];
export const app = express();
app.post("/webhooks/github", express.text({ type: "application/json" }), async (req, res) => {
  const signature = req.get("x-hub-signature-256");
  if (!signature || !(await webhooks.verify(req.body, signature))) {
    return res.sendStatus(401);
  }
  const event = JSON.parse(req.body);
  types.push(event.action);
  return res.sendStatus(204);
});

import { Webhook } from "svix";

const webhook = new Webhook(process.env.CLERK_WEBHOOK_SECRET);
const updates = [];
export async function POST(request) {
  const raw = await request.text();
  try {
    const message = webhook.verify(raw, Object.fromEntries(request.headers));
    updates.push(message.type);
    return new Response(null, { status: 202 });
  } catch {
    return new Response(null, { status: 400 });
  }
}

import express from "express";
import Stripe from "stripe";

const router = express.Router();
const stripe = new Stripe(process.env.STRIPE_API_KEY);
const settled = [];
router.post("/billing/webhooks/stripe", express.raw({ type: "application/json" }), (req, res) => {
  let event;
  try {
    event = stripe.webhooks.constructEvent(req.body, req.headers["stripe-signature"], process.env.STRIPE_ENDPOINT_SECRET);
  } catch {
    return res.status(400).end();
  }
  settled.push(event.id);
  return res.status(204).end();
});
export default router;

